package ktanesolver.module.modded.regular.yellowarrows;import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;
class YellowArrowsSolverTest{@Test void advancesFiveRowsAndStoresStartingRow(){BombEntity b=new BombEntity();b.setSerialNumber("AB1CD2");ModuleEntity m=new ModuleEntity();YellowArrowsSolver s=new YellowArrowsSolver();String[]rows={"D","G","J","M","P"};for(int i=0;i<5;i++){YellowArrowsOutput o=solve(s,b,m,i==0);assertThat(o.ruleRow()).isEqualTo(rows[i]);assertThat(o.pressNumber()).isEqualTo(i+1);}assertThat(m.getState()).containsEntry("yellowArrowsStartingRow","A");}@SuppressWarnings("unchecked")private static YellowArrowsOutput solve(YellowArrowsSolver s,BombEntity b,ModuleEntity m,boolean reset){return((SolveSuccess<YellowArrowsOutput>)s.solve(new RoundEntity(),b,m,new YellowArrowsInput("A",reset))).output();}}
